    public static IEnumerable<object[]> Data() => Enumerable.Range(0, Cases.Length).Select(i => new object[] { i });

    private static string Norm(string s)
    {
        s = s.Trim().ToLowerInvariant();
        s = Regex.Replace(s, @"\s+", " ");
        s = Regex.Replace(s, @"\s*,\s*", ", ");
        return Regex.Replace(s, @"(?<![\w.])\+?(\d*\.\d+|\d+\.?)(e[+-]?\d+)?", m => double.Parse(m.Value, CultureInfo.InvariantCulture).ToString("0.######", CultureInfo.InvariantCulture));
    }

    [Theory]
    [MemberData(nameof(Data))]
    public void Matches_Chrome(int index)
    {
        (string declaration, bool accepted, string[] values) = Cases[index];
        Document doc = Document.Parse("<div style=\"" + (Pre + declaration).Replace("\"", "&quot;") + "\"></div>");
        ComputedStyle style = DocumentStyles.Create(doc).GetStyle(doc.Root.DescendantElements.First(e => e.LocalName == "div"));
        foreach (string v in values)
        {
            int eq = v.IndexOf('=');
            Assert.True(Norm(style.GetPropertyValue(v[..eq])) == Norm(v[(eq + 1)..]), declaration + ": " + v[..eq] + " is " + style.GetPropertyValue(v[..eq]) + ", Chrome has " + v[(eq + 1)..]);
        }

        // A shorthand resets the sentinel when it is accepted; a rejected declaration leaves it.
        string name = declaration[..declaration.IndexOf(':')];
        if (name is "transition" or "-webkit-transition" or "animation" or "-webkit-animation")
        {
            string probe = name.EndsWith("transition", System.StringComparison.Ordinal) ? "transition-property" : "animation-name";
            Assert.Equal(accepted, !style.GetPropertyValue(probe).Equals("SENT", System.StringComparison.OrdinalIgnoreCase));
        }
    }
